// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: Store scenarios for the human editing a draft while an agent works on it (per-part merge of stale saves,
//          conflicts naming the part) and for export naming / simulation inputs written to the project from a draft view.

import { beforeEach, describe, expect, it } from 'vitest'
import { updatedByAgent } from '#/lib/drafts'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from './db.server'
import { createProjectStore, type ProjectStore } from './projects.server'

let time: number
let store: ProjectStore

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

const expressions = (): ProjectData => ({
  ...defaultProjectData(),
  def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
  ll: { grammar: 'E -> id', input: 'id + id' },
  prec: { terminals: ['+', 'id'], cells: {}, rules: 'E -> E + E\nE -> id', input: 'id' },
  names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
})

function openDraft() {
  const project = store.createProject('Výrazy', expressions())
  const draft = store.createDraft(project.id, 'Oprava konfliktu', 'agent')!
  return { project, draft }
}

describe('the human saves a draft an agent is working on', () => {
  it('a stale save of the precedence table merges with the agent’s new grammar rules', () => {
    const { draft } = openDraft()
    // The human opened the draft at revision 1; meanwhile an agent rewrites the grammar rules.
    store.editDraft(draft.id, { grammarRules: 'E -> id R\nR -> + E\nR -> eps' }, { author: 'agent' })

    const precTable = { terminals: ['+', 'id'], cells: { 'id\u0001+': '>' as const } }
    const result = store.editDraft(draft.id, { precTable }, { author: 'human', baseRevision: 1 })

    expect(result).toMatchObject({ status: 'saved', changed: ['precTable'], draft: { revision: 3 } })
    const merged = store.getDraft(draft.id)!
    expect(merged.parts.grammarRules).toBe('E -> id R\nR -> + E\nR -> eps')
    expect(merged.parts.precTable).toEqual(precTable)
  })

  it('a stale save of the same part the agent changed is a conflict naming that part, and nothing is written', () => {
    const { draft } = openDraft()
    store.editDraft(draft.id, { grammarRules: 'E -> id R' }, { author: 'agent' })

    const result = store.editDraft(draft.id, { grammarRules: 'E -> id + E', reductionRules: 'E -> id' }, { author: 'human', baseRevision: 1 })

    expect(result).toMatchObject({ status: 'conflict', parts: ['grammarRules'], draft: { revision: 2 } })
    expect(store.getDraft(draft.id)!.parts).toMatchObject({ grammarRules: 'E -> id R', reductionRules: 'E -> E + E\nE -> id' })
  })

  it('a human save is a human change: the draft is not "updated by agent" afterwards', () => {
    const { draft } = openDraft()
    store.editDraft(draft.id, { grammarRules: 'E -> id R' }, { author: 'agent' })
    expect(updatedByAgent(store.getDraft(draft.id)!)).toBe(true)

    store.editDraft(draft.id, { reductionRules: 'E -> id' }, { author: 'human', baseRevision: 2 })
    expect(store.getDraft(draft.id)).toMatchObject({ lastChangedBy: 'human' })
    expect(updatedByAgent(store.getDraft(draft.id)!)).toBe(false)
  })
})

describe('export naming and simulation inputs edited in a draft view', () => {
  it('are written to the project and bump the project’s revision, not the draft’s', () => {
    const { project, draft } = openDraft()
    time += 1000

    const names = { ...expressions().names, ntPrefix: 'NT_' }
    const result = store.saveProjectSettings(project.id, { names, llInput: 'id', precInput: 'id + id' })

    expect(result).toEqual({ status: 'saved', revision: 2, updatedAt: '2026-01-01T10:00:01.000Z' })
    const saved = store.getProject(project.id)!
    expect(saved.revision).toBe(2)
    expect(saved.data).toEqual({ ...expressions(), names, ll: { grammar: 'E -> id', input: 'id' }, prec: { ...expressions().prec, input: 'id + id' } })
    expect(store.getDraft(draft.id)).toMatchObject({ revision: 1 })
  })

  it('never touch the project’s parts, even when they changed since the draft was opened', () => {
    const { project } = openDraft()
    store.saveProject(project.id, { ...expressions(), ll: { grammar: 'E -> x', input: 'id + id' } }, 1)

    store.saveProjectSettings(project.id, { names: expressions().names, llInput: 'x', precInput: 'id' })

    expect(store.getProject(project.id)!.data.ll).toEqual({ grammar: 'E -> x', input: 'x' })
  })

  it('unchanged settings keep the revision; a deleted project is missing', () => {
    const { project } = openDraft()
    const same = { names: expressions().names, llInput: 'id + id', precInput: 'id' }
    expect(store.saveProjectSettings(project.id, same)).toMatchObject({ status: 'saved', revision: 1 })
    expect(store.saveProjectSettings('nope', same)).toEqual({ status: 'missing' })
  })
})
